def make_question(index, row):
    tag, prompt, options, answer, reason = row
    opts = [{"id": chr(65+i), "text": text} for i, text in enumerate(options)]
    aid = next(o["id"] for o in opts if o["text"] == answer)
    refs = [{"url": u, "title": f"{t}；僅研究公開題型與能力方向，未複製原題。", "year": "113-114", "subject": "social", "locator": l, "observedPattern": "公立學校社會科公開試題常見的土地利用、災害風險與環境政策推理能力，經本題重新設計。", "reuseDecision": "pattern-only", "status": "recorded", "locatorLevel": "paper"} for u,t,l in SOURCES]
